package com.mlmvpn.scanner.ui

import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.*
import androidx.compose.ui.graphics.vector.ImageVector

// =================================================================================================
// The changelog, as data.
//
// This is fifteen hundred lines of release notes in two languages, and it used to live inside the
// composable that drew them -- which meant every edit to the SCREEN happened somewhere in the
// middle of the CONTENT, and the file was 1840 lines of which 1500 were prose. Nothing here is
// UI: it is the text, unchanged, moved out so the screen beside it can be read in one sitting.
//
// Adding a release means adding a ChangelogVersion at the TOP of each list. Both lists carry the
// same versions -- the Persian one is what almost every user sees, and the English one is not a
// fallback for missing entries, it is the same content for an English device.
// =================================================================================================

/** One line item: what changed, and enough of why to be worth reading. */
data class ChangelogItem(
    val title: String,
    val description: String,
    val icon: ImageVector,
)

/** One release, newest first. */
data class ChangelogVersion(
    val versionTitle: String,
    val items: List<ChangelogItem>,
)

/** Every release, in the language the app is running in. */
